import zlib from "node:zlib";

const decode = (value) => JSON.parse(zlib.gunzipSync(Buffer.from(value, "base64")).toString("utf8"));

const recoveryEnvelopeBytes = "";
const originalPreparationBytes = "";

export const partialRecoveryEnvelopeFixture = () => decode(recoveryEnvelopeBytes);
export const partialRecoveryOriginalPreparationFixture = () => decode(originalPreparationBytes);
